	import { getWordsAll } from '@/api/diy'
    import vuedraggable from 'vuedraggable'
    export default {
        name: 'c_hot_word',
        props: {
            configObj: {
                type: Object
            },
            configNme: {
                type: String
            }
        },
        components: {
            draggable: vuedraggable
        },
        data () {
            return {
                hotWordList: [],
                hotIndex: 1,
                defaults: {},
                configData: {},
				wordList: []
            }
        },
        created () {
            this.defaults = this.configObj
            this.configData = this.configObj[this.configNme]
			this.wordsAll();
        },
        watch: {
            configObj: {
                handler (nVal, oVal) {
                    // this.hotWordList = nVal.hotList
                    this.configData = nVal[this.configNme]
                },
                immediate: true,
                deep: true
            }
        },
        methods: {
			wordsAll(){
				getWordsAll().then(res=>{
					this.wordList = res.data;
				}).catch(err=>{
					this.$Message.error(err.msg);
				})
			},
            addHotTxt () {
                // let obj = {}
                // if(this.configData.list.length){
                //     obj = JSON.parse(JSON.stringify(this.configData.list[this.configData.list.length - 1]))
                // }else {
                //     obj = {
                //         val: ''
                //     }
                // }
                let obj = {
                    val: ''
                };
                this.configData.list.push(obj)
                // this.$emit('input', this.hotWordList);
            },
            // 删除数组
            bindDelete (index) {
                this.configData.list.splice(index, 1)
            },
        }
    }
